package com.agriconnect.analytics;import java.math.*;import java.util.*;import org.springframework.amqp.core.*;import org.springframework.amqp.rabbit.annotation.RabbitListener;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Configuration class AnalyticsEvents{@Bean TopicExchange events(@Value("${events.exchange}")String n){return new TopicExchange(n,true,false);}@Bean org.springframework.amqp.core.Queue analyticsDlq(){return QueueBuilder.durable("analytics.events.dlq").build();}@Bean org.springframework.amqp.core.Queue analyticsQueue(){return QueueBuilder.durable("analytics.events").deadLetterExchange("").deadLetterRoutingKey("analytics.events.dlq").build();}@Bean Declarables analyticsBindings(org.springframework.amqp.core.Queue analyticsQueue,TopicExchange events){return new Declarables(BindingBuilder.bind(analyticsQueue).to(events).with("crop.#"),BindingBuilder.bind(analyticsQueue).to(events).with("inventory.#"),BindingBuilder.bind(analyticsQueue).to(events).with("rescue.#"),BindingBuilder.bind(analyticsQueue).to(events).with("order.#"),BindingBuilder.bind(analyticsQueue).to(events).with("shipment.#"));}}
@Component class ReadModelConsumer{private final JdbcClient db;ReadModelConsumer(JdbcClient d){db=d;}@RabbitListener(queues="analytics.events")@Transactional void consume(Map<String,Object>event){UUID id=UUID.fromString(String.valueOf(event.get("eventId")));if(db.sql("select count(*) from processed_events where event_id=:id").param("id",id).query(Long.class).single()>0)return;String type=String.valueOf(event.get("eventType"));Map<?,?>p=(Map<?,?>)event.get("payload");if(type.startsWith("CropBatch"))crop(p);else if(type.startsWith("Inventory"))inventory(type,p);else if(type.startsWith("Rescue"))rescue(p);else if(type.startsWith("Order"))order(p);else if(type.startsWith("Shipment"))shipment(p);db.sql("insert into processed_events(event_id)values(:id)").param("id",id).update();}
private void crop(Map<?,?>p){db.sql("insert into crop_batch_snapshots(batch_id,crop_id,farmer_id,initial_quantity,available_quantity,reserved_quantity,sold_quantity,province,expiry_date,status)values(:id,:c,:f,:i,:a,:r,:s,:p,cast(:e as date),:st) on conflict(batch_id)do update set crop_id=excluded.crop_id,farmer_id=excluded.farmer_id,initial_quantity=excluded.initial_quantity,available_quantity=excluded.available_quantity,reserved_quantity=excluded.reserved_quantity,sold_quantity=excluded.sold_quantity,province=excluded.province,expiry_date=excluded.expiry_date,status=excluded.status,updated_at=now()").param("id",p.get("batchId")).param("c",p.get("cropId")).param("f",p.get("farmerId")).param("i",p.get("initialQuantity")).param("a",p.get("availableQuantity")).param("r",p.get("reservedQuantity")).param("s",p.get("soldQuantity")).param("p",p.get("province")).param("e",p.get("expiryDate")).param("st",p.get("status")).update();db.sql("insert into inventory_snapshots(batch_id,available_quantity,reserved_quantity,sold_quantity)values(:id,:a,:r,:s)on conflict(batch_id)do update set available_quantity=excluded.available_quantity,reserved_quantity=excluded.reserved_quantity,sold_quantity=excluded.sold_quantity,updated_at=now()").param("id",p.get("batchId")).param("a",p.get("availableQuantity")).param("r",p.get("reservedQuantity")).param("s",p.get("soldQuantity")).update();}
private void inventory(String type,Map<?,?>p){if(db.sql("select count(*) from inventory_snapshots where batch_id=:id").param("id",p.get("cropBatchId")).query(Long.class).single()==0)return;BigDecimal q=new BigDecimal(String.valueOf(p.get("quantity")));String sql=switch(type){case"InventoryReserved"->"update inventory_snapshots set available_quantity=available_quantity-:q,reserved_quantity=reserved_quantity+:q,updated_at=now()where batch_id=:id";case"InventoryCommitted"->"update inventory_snapshots set reserved_quantity=reserved_quantity-:q,sold_quantity=sold_quantity+:q,updated_at=now()where batch_id=:id";default->"update inventory_snapshots set reserved_quantity=reserved_quantity-:q,available_quantity=available_quantity+:q,updated_at=now()where batch_id=:id";};db.sql(sql).param("q",q).param("id",p.get("cropBatchId")).update();}
private void rescue(Map<?,?>p){db.sql("insert into rescue_facts(registration_id,crop_batch_id,farmer_id,rescue_point_id,status)values(:id,:b,:f,:r,:s)on conflict(registration_id)do update set status=excluded.status,updated_at=now()").param("id",p.get("registrationId")).param("b",p.get("cropBatchId")).param("f",p.get("farmerId")).param("r",p.get("rescuePointId")).param("s",p.get("status")).update();}
private void order(Map<?,?>p){db.sql("insert into order_facts(order_id,buyer_id,total_amount,status)values(:id,:b,coalesce(:t,0),:s)on conflict(order_id)do update set status=excluded.status,total_amount=coalesce(excluded.total_amount,order_facts.total_amount),updated_at=now()").param("id",p.get("orderId")).param("b",p.get("buyerId")).param("t",p.get("totalAmount")).param("s",p.get("status")).update();}
private void shipment(Map<?,?>p){db.sql("insert into shipment_facts(shipment_id,order_id,status)values(:id,:o,:s)on conflict(shipment_id)do update set status=excluded.status,updated_at=now()").param("id",p.get("shipmentId")).param("o",p.get("orderId")).param("s",p.get("status")).update();}}
